{
  "states": [
    "STABLE",
    "CHANGING",
    "UNSTABLE"
  ],
  "transitions": [
    {
      "from": "STABLE",
      "event": "",
      "action": "snd Change L",
      "to": "CHANGING"
    },
    {
      "from": "CHANGING",
      "event": "pref list changes",
      "action": "",
      "to": "UNSTABLE"
    },
    {
      "from": "UNSTABLE",
      "event": "snd Change L",
      "action": "",
      "to": "CHANGING"
    },
    {
      "from": "CHANGING",
      "event": "rcv Confirm R",
      "action": "accept value, snd Confirm L",
      "to": "STABLE"
    },
    {
      "from": "CHANGING",
      "event": "rcv empty Confirm R",
      "action": "revert to old value",
      "to": "STABLE"
    },
    {
      "from": "UNSTABLE",
      "event": "rcv Confirm/Change R",
      "action": "ignore",
      "to": "UNSTABLE"
    }
  ]
}

{
  "states": [
    "CLOSED",
    "REQUEST",
    "PARTOPEN",
    "LISTEN",
    "RESPOND",
    "OPEN",
    "CLOSEREQ",
    "CLOSING",
    "TIMEWAIT"
  ],
  "transitions": [
    {
      "from": "CLOSED",
      "event": "",
      "action": "snd Request",
      "to": "REQUEST"
    },
    {
      "from": "LISTEN",
      "event": "rcv Request",
      "action": "Generate Response",
      "to": "RESPOND"
    },
    {
      "from": "LISTEN",
      "event": "Init Cookie option received",
      "action": "Generate Response",
      "to": "RESPOND"
    },
    {
      "from": "REQUEST",
      "event": "snd Request",
      "action": "",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "rcv Response",
      "action": "Move to PARTOPEN",
      "to": "PARTOPEN"
    },
    {
      "from": "RESPOND",
      "event": "rcv Request",
      "action": "Send Response",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "rcv Ack/DataAck",
      "action": "Move to OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "snd Ack",
      "action": "",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "rcv packet (not Response/Reset/Sync)",
      "action": "Move to OPEN",
      "to": "OPEN"
    },
    {
      "from": "RESPOND",
      "event": "timeout >= 4MSL",
      "action": "Send Reset Aborted, Move to CLOSED",
      "to": "CLOSED"
    },
    {
      "from": "OPEN",
      "event": "server active close (snd CloseReq)",
      "action": "",
      "to": "CLOSEREQ"
    },
    {
      "from": "OPEN",
      "event": "active close or rcv CloseReq",
      "action": "snd Close",
      "to": "CLOSING"
    },
    {
      "from": "CLOSEREQ",
      "event": "rcv Close",
      "action": "Send Reset",
      "to": "CLOSED"
    },
    {
      "from": "CLOSING",
      "event": "snd Close",
      "action": "",
      "to": "CLOSING"
    },
    {
      "from": "CLOSING",
      "event": "rcv Reset",
      "action": "Move to TIMEWAIT",
      "to": "TIMEWAIT"
    },
    {
      "from": "OPEN",
      "event": "client active close (snd Close)",
      "action": "",
      "to": "CLOSING"
    },
    {
      "from": "CLOSING",
      "event": "rcv Reset",
      "action": "Move to TIMEWAIT",
      "to": "TIMEWAIT"
    },
    {
      "from": "CLOSEREQ",
      "event": "snd CloseReq",
      "action": "",
      "to": "CLOSEREQ"
    },
    {
      "from": "CLOSING",
      "event": "rcv Reset",
      "action": "Move to TIMEWAIT",
      "to": "TIMEWAIT"
    },
    {
      "from": "TIMEWAIT",
      "event": "2MSL timer expires",
      "action": "",
      "to": "CLOSED"
    }
  ]
}
